// Validates if the invoice amount is strictly within the approver's financial authority
if ($net_amount > $amount_limit) {
    // Must return a string
    return `HARD VIOLATION: The invoice net amount (${$net_amount}) exceeds the strict approval limit (${$amount_limit}) allowed for ${$approver_name}.`;
} else {
    return "PASS: The approval limit is valid and sufficient for this transaction amount.";
}
